begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values ('30000000-0000-4000-8000-000000000001','association-1@example.invalid');
insert into auth.users(id,email) values ('30000000-0000-4000-8000-000000000002','association-2@example.invalid');
insert into auth.users(id,email) values ('30000000-0000-4000-8000-000000000003','association-3@example.invalid');
insert into public.households(id,name) values ('30000100-0000-4000-8000-000000000001','Association home 1');
insert into public.households(id,name) values ('30000100-0000-4000-8000-000000000002','Association home 2');
insert into public.household_members(household_id,user_id,display_name) values ('30000100-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','Member 1');
insert into public.household_members(household_id,user_id,display_name) values ('30000100-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002','Member 2');
insert into public.household_members(household_id,user_id,display_name) values ('30000100-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000003','Member 3');
insert into public.household_projects(id,household_id,created_by,kind,title) values ('30000200-0000-4000-8000-000000000001','30000100-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','trip','Trip 1');
insert into public.household_projects(id,household_id,created_by,kind,title) values ('30000200-0000-4000-8000-000000000002','30000100-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','trip','Trip 2');
insert into public.household_projects(id,household_id,created_by,kind,title) values ('30000200-0000-4000-8000-000000000003','30000100-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000003','trip','Trip 3');
insert into public.trip_bookings(id,household_id,created_by,project_id,kind,title) values ('30000500-0000-4000-8000-000000000001','30000100-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','30000200-0000-4000-8000-000000000001','flight','Flight');
insert into public.household_assets(id,household_id,created_by,title) values ('30000300-0000-4000-8000-000000000001','30000100-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','Appliance');
insert into public.household_commitments(id,household_id,created_by,title) values ('30000400-0000-4000-8000-000000000001','30000100-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','Contract');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select set_config('test.event',public.post_manual_expense('30000100-0000-4000-8000-000000000001','Already paid',101,'30000000-0000-4000-8000-000000000001','[{"memberId":"30000000-0000-4000-8000-000000000001","allocatedCents":51},{"memberId":"30000000-0000-4000-8000-000000000002","allocatedCents":50}]','2026-09-05','association-existing')->>'financial_event_id',true);
reset role;
create function pg_temp.assign(p_key integer, p_changes jsonb default '{}'::jsonb) returns jsonb language sql as $fn$
with input as (select jsonb_build_object('household','30000100-0000-4000-8000-000000000001','event',current_setting('test.event'),'kind','project','context','30000200-0000-4000-8000-000000000001','booking',null,'revision',(select revision from public.household_financial_links where financial_event_id=current_setting('test.event')::uuid)) || p_changes as v)
select public.assign_expense_context((v->>'household')::uuid,(v->>'event')::uuid,(v->>'revision')::uuid,('30000900-0000-4000-8000-'||lpad(p_key::text,12,'0'))::uuid,v->>'kind',(v->>'context')::uuid,(v->>'booking')::uuid) from input;
$fn$;
select ok((select relrowsecurity from pg_class where oid='private.expense_context_change_receipts'::regclass),'private receipt RLS enabled');
select ok(not has_table_privilege('authenticated','private.expense_context_change_receipts','select,insert,update,delete'),'members cannot forge private receipts');
select ok(not has_table_privilege('anon','private.expense_context_change_receipts','select,insert,update,delete'),'anonymous cannot access private receipts');
set local role anon;
select throws_ok($$select pg_temp.assign(1)$$,'42501',null,'anonymous cannot assign expenses');
set local role authenticated;
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select pg_temp.assign(1)$$,'42501',null,'missing identity rejected');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
select throws_ok($$select pg_temp.assign(1)$$,'42501',null,'foreign household actor rejected');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
select throws_ok($$select pg_temp.assign(1,'{"context":"30000200-0000-4000-8000-000000000003"}')$$,'42501',null,'foreign target rejected');
select throws_ok($$select pg_temp.assign(1,'{"kind":"other"}')$$,'22023',null,'invalid kind rejected');
select throws_ok($$select pg_temp.assign(1,'{"context":null}')$$,'22023',null,'incomplete target rejected');
select throws_ok($$select pg_temp.assign(1,'{"event":"30000000-0000-4000-8000-000000000003"}')$$,'42501',null,'missing event rejected');
select throws_ok($$select pg_temp.assign(1,'{"context":"30000200-0000-4000-8000-000000000002","booking":"30000500-0000-4000-8000-000000000001"}')$$,'22023',null,'booking must belong to chosen project');
select lives_ok($$select pg_temp.assign(1,'{"revision":null}')$$,'existing expense is associated');
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000001')->>'paid_cents','101','paid total derives existing event');
select set_config('test.revision',(select revision::text from public.household_financial_links where financial_event_id=current_setting('test.event')::uuid),true);
select lives_ok($$select pg_temp.assign(1,'{"revision":null}')$$,'identical request replays despite newer revision');
select is((select revision::text from public.household_financial_links where financial_event_id=current_setting('test.event')::uuid),current_setting('test.revision'),'retry does not rewrite link');
select throws_ok($$select pg_temp.assign(1,'{"revision":null,"context":"30000200-0000-4000-8000-000000000002"}')$$,'22023',null,'retry cannot use different payload');
select throws_ok($$select pg_temp.assign(2,'{"revision":null}')$$,'40001',null,'stale missing association cannot overwrite');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000002',true);
select lives_ok($$select pg_temp.assign(2,'{"context":"30000200-0000-4000-8000-000000000002"}')$$,'partner may reassign');
select throws_ok($$select pg_temp.assign(3,jsonb_build_object('revision',current_setting('test.revision')))$$,'40001',null,'old partner confirmation rejected');
select lives_ok($$select pg_temp.assign(1,'{"revision":null}')$$,'old successful replay acknowledges without undoing partner');
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000001')->>'paid_cents','0','original context no longer includes reassigned payment');
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000002')->>'paid_cents','101','new context contains same payment');
select lives_ok($$select pg_temp.assign(3,'{"kind":null,"context":null}')$$,'remove direct association');
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000002')->>'paid_cents','0','removed association stops context total');
select lives_ok($$select pg_temp.assign(4,'{"kind":"asset","context":"30000300-0000-4000-8000-000000000001"}')$$,'restore association onto inventory');
select is(public.read_household_cost_context('asset','30000300-0000-4000-8000-000000000001')->>'paid_cents','101','inventory receives exact cost');
select lives_ok($$select pg_temp.assign(5,'{"kind":"commitment","context":"30000400-0000-4000-8000-000000000001"}')$$,'commitment accepts recorded expense');
select is(public.read_household_cost_context('commitment','30000400-0000-4000-8000-000000000001')->>'paid_cents','101','commitment receives exact cost');
select throws_ok($$update public.household_financial_links set financial_event_id='30000000-0000-4000-8000-000000000001' where financial_event_id=current_setting('test.event')::uuid$$,'23514',null,'direct update cannot replace association event identity');
update public.household_projects set archived_at=now() where id='30000200-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.assign(6)$$,'22023',null,'archived target rejects assignment');
update public.household_projects set archived_at=null where id='30000200-0000-4000-8000-000000000001';
update public.trip_bookings set archived_at=now() where id='30000500-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.assign(6,'{"booking":"30000500-0000-4000-8000-000000000001"}')$$,'22023',null,'archived booking rejects assignment');
update public.trip_bookings set archived_at=null where id='30000500-0000-4000-8000-000000000001';
select lives_ok($$select pg_temp.assign(6,'{"booking":"30000500-0000-4000-8000-000000000001"}')$$,'active booking receives existing payment');
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000001',p_booking_id=>'30000500-0000-4000-8000-000000000001')->>'paid_cents','101','booking derives existing payment');
-- Property: arbitrary repeated reassignment never changes event count or ledger.
reset role;
create function pg_temp.check_association_sequences() returns setof text language plpgsql as $fn$
declare i integer; choice integer; target uuid; before_ledger jsonb; after_ledger jsonb;
begin
  select jsonb_agg(to_jsonb(l) order by id) into before_ledger from public.ledger_entries l where household_id='30000100-0000-4000-8000-000000000001';
  for i in 1..40 loop
    choice := 1+floor(random()*2)::integer;
    target := ('30000200-0000-4000-8000-'||lpad(choice::text,12,'0'))::uuid;
    perform pg_temp.assign(100+i,jsonb_build_object('context',target));
    return next is(public.read_household_cost_context('project',target)->>'paid_cents','101','sequence preserves exact target total '||i);
    return next is((select count(*) from public.financial_events where household_id='30000100-0000-4000-8000-000000000001'),1::bigint,'sequence never posts another payment '||i);
    select jsonb_agg(to_jsonb(l) order by id) into after_ledger from public.ledger_entries l where household_id='30000100-0000-4000-8000-000000000001';
    return next is(after_ledger,before_ledger,'sequence preserves every ledger row '||i);
  end loop;
end;
$fn$;
set local role authenticated;
select * from pg_temp.check_association_sequences();
select set_config('test.refund',public.post_refund(current_setting('test.event')::uuid,25,'[{"memberId":"30000000-0000-4000-8000-000000000001","allocatedCents":13},{"memberId":"30000000-0000-4000-8000-000000000002","allocatedCents":12}]','2026-09-05','association-refund','Partial refund')->>'financial_event_id',true);
select lives_ok($$select pg_temp.assign(200)$$,'reassignment carries inherited refund');
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000001')->>'paid_cents','76','refund follows payment exactly');
select throws_ok($$select pg_temp.assign(201,jsonb_build_object('event',current_setting('test.refund'),'revision',null))$$,'42501',null,'refund cannot receive independent association');
select lives_ok($$select public.correct_financial_event(current_setting('test.refund')::uuid,'association-reverse-refund')$$,'reverse mistaken refund');
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000001')->>'paid_cents','101','refund reversal also follows association');
select set_config('test.replacement',public.correct_financial_event(current_setting('test.event')::uuid,'association-replacement','{"payer_member_id":"30000000-0000-4000-8000-000000000001","description":"Corrected payment","amount_cents":81,"allocations":[{"memberId":"30000000-0000-4000-8000-000000000001","allocatedCents":41},{"memberId":"30000000-0000-4000-8000-000000000002","allocatedCents":40}],"occurred_on":"2026-09-05"}')->>'replacement_event_id',true);
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000001')->>'paid_cents','81','replacement inherits original association');
select lives_ok($$select pg_temp.assign(202,jsonb_build_object('event',current_setting('test.replacement'),'revision',null,'context','30000200-0000-4000-8000-000000000002'))$$,'replacement can explicitly override context');
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000001')->>'paid_cents','0','original and reversal remain together');
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000002')->>'paid_cents','81','replacement appears only in override');
select lives_ok($$select pg_temp.assign(203,jsonb_build_object('event',current_setting('test.replacement'),'revision',(select revision from public.household_financial_links where financial_event_id=current_setting('test.replacement')::uuid),'kind',null,'context',null))$$,'removing replacement override restores inheritance');
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000001')->>'paid_cents','81','removed override returns replacement to original context');
select is(public.read_household_cost_context('project','30000200-0000-4000-8000-000000000002')->>'paid_cents','0','removed override leaves no stale cost');
-- A receipt failure must roll back the association and its revision together.
select set_config('test.before_failure',(select to_jsonb(l)::text from public.household_financial_links l where financial_event_id=current_setting('test.event')::uuid),true);
reset role;
create function pg_temp.reject_context_receipt() returns trigger language plpgsql as $fn$
begin
  if new.request_id='30000900-0000-4000-8000-000000000999'::uuid then raise exception 'fixture receipt failure'; end if;
  return new;
end;
$fn$;
create trigger fixture_context_receipt_failure before insert on private.expense_context_change_receipts for each row execute function pg_temp.reject_context_receipt();
set local role authenticated;
select throws_ok($$select pg_temp.assign(999,'{"context":"30000200-0000-4000-8000-000000000002"}')$$,'P0001','fixture receipt failure','failed receipt rolls back reassignment');
select is((select to_jsonb(l) from public.household_financial_links l where financial_event_id=current_setting('test.event')::uuid),current_setting('test.before_failure')::jsonb,'failed transaction preserves complete association snapshot');
reset role;
select is((select count(*) from private.expense_context_change_receipts where request_id='30000900-0000-4000-8000-000000000999'),0::bigint,'failed request leaves no receipt');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.household_financial_links),0::bigint,'other household cannot read associations');
select is((select count(*) from public.household_financial_links where financial_event_id=current_setting('test.event')::uuid),0::bigint,'event ID cannot reveal a foreign association');
reset role;
select * from finish();
rollback;
